'use client'

import * as React from 'react'
import { buttonVariants, cn } from "@/lib/utils"
import { createPortal } from 'react-dom'

import { Slot } from './slot'

const AlertDialogContext = React.createContext<{
  open: boolean
  setOpen: (open: boolean) => void
} | null>(null)

function useAlertDialog() {
  const context = React.useContext(AlertDialogContext)
  if (!context) {
    throw new Error('AlertDialog components must be used within AlertDialog')
  }
  return context
}

const AlertDialog = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    open?: boolean
    defaultOpen?: boolean
    onOpenChange?: (open: boolean) => void
  }
>(({ children, open, defaultOpen, onOpenChange, ...props }, ref) => {
  const [isOpen, setIsOpen] = React.useState<boolean>(
    open !== undefined ? open : (defaultOpen ?? false)
  )

  React.useEffect(() => {
    if (open !== undefined) {
      setIsOpen(open)
    }
  }, [open])

  const handleOpenChange = React.useCallback(
    (value: boolean) => {
      if (open === undefined) {
        setIsOpen(value)
      }
      onOpenChange?.(value)
    },
    [open, onOpenChange]
  )

  const contextValue = React.useMemo(
    () => ({
      open: isOpen,
      setOpen: handleOpenChange,
    }),
    [isOpen, handleOpenChange]
  )

  return <AlertDialogContext.Provider value={contextValue}>{children}</AlertDialogContext.Provider>
})
AlertDialog.displayName = 'AlertDialog'

const AlertDialogTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }
>(({ className, onClick, asChild = false, ...props }, ref) => {
  const { setOpen } = useAlertDialog()
  const Comp = asChild ? Slot : 'button'
  return (
    <Comp
      ref={ref}
      data-slot="alert-dialog-trigger"
      type="button"
      onClick={(e) => {
        setOpen(true)
        onClick?.(e)
      }}
      className={cn(className)}
      {...props}
    />
  )
})
AlertDialogTrigger.displayName = 'AlertDialogTrigger'

const AlertDialogPortal = ({ children }: { children: React.ReactNode }) => {
  const { open } = useAlertDialog()

  if (!open) return null
  if (typeof window === 'undefined') return null

  return createPortal(<div data-slot="alert-dialog-portal">{children}</div>, document.body)
}
AlertDialogPortal.displayName = 'AlertDialogPortal'

const AlertDialogOverlay = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        data-slot="alert-dialog-overlay"
        data-state="open"
        className={cn(
          'fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0',
          className
        )}
        {...props}
      />
    )
  }
)
AlertDialogOverlay.displayName = 'AlertDialogOverlay'

const AlertDialogContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => {
    return (
      <AlertDialogPortal>
        <AlertDialogOverlay />
        <div
          ref={ref}
          data-slot="alert-dialog-content"
          data-state="open"
          className={cn(
            'fixed left-[50%] top-[50%] z-50 grid w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            className
          )}
          {...props}
        >
          {children}
        </div>
      </AlertDialogPortal>
    )
  }
)
AlertDialogContent.displayName = 'AlertDialogContent'

const AlertDialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn('flex flex-col space-y-2 text-center sm:text-left', className)} {...props} />
)
AlertDialogHeader.displayName = 'AlertDialogHeader'

const AlertDialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn('flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2', className)}
    {...props}
  />
)
AlertDialogFooter.displayName = 'AlertDialogFooter'

const AlertDialogTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => (
  <h2
    ref={ref}
    data-slot="alert-dialog-title"
    className={cn('text-lg font-semibold', className)}
    {...props}
  />
))
AlertDialogTitle.displayName = 'AlertDialogTitle'

const AlertDialogDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <p
    ref={ref}
    data-slot="alert-dialog-description"
    className={cn('text-muted-foreground text-sm', className)}
    {...props}
  />
))
AlertDialogDescription.displayName = 'AlertDialogDescription'

const AlertDialogAction = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement>
>(({ className, onClick, ...props }, ref) => {
  const { setOpen } = useAlertDialog()
  return (
    <button
      ref={ref}
      type="button"
      onClick={(e) => {
        setOpen(false) // Action confirms and closes
        onClick?.(e)
      }}
      className={cn(buttonVariants(), className)}
      {...props}
    />
  )
})
AlertDialogAction.displayName = 'AlertDialogAction'

const AlertDialogCancel = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement>
>(({ className, onClick, ...props }, ref) => {
  const { setOpen } = useAlertDialog()
  return (
    <button
      ref={ref}
      type="button"
      onClick={(e) => {
        setOpen(false)
        onClick?.(e)
      }}
      className={cn(buttonVariants({ variant: 'outline' }), 'mt-2 sm:mt-0', className)}
      {...props}
    />
  )
})
AlertDialogCancel.displayName = 'AlertDialogCancel'

export {
  AlertDialog,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogTrigger,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
}

import { inject, provide, type ComputedRef } from 'vue'
import type { dialogConnect } from "@/lib/utils"

export type AlertDialogContext = ComputedRef<ReturnType<typeof dialogConnect>>

export const AlertDialogContextKey = Symbol('AlertDialogContext')

export const provideAlertDialogContext = (context: AlertDialogContext) => {
    provide(AlertDialogContextKey, context)
}

export const useAlertDialogContext = (): AlertDialogContext => {
    const context = inject(AlertDialogContextKey)
    if (!context) {
        throw new Error('AlertDialog components must be used within a `<AlertDialog />` provider.')
    }
    return context as AlertDialogContext
}

import { computed, watch } from 'vue'
import type { AlertDialogVueProps as CoreAlertDialogProps } from "@/lib/utils"
import { normalizeProps, useMachine } from '@zag-js/vue'
import { dialogConnect, dialogMachine } from "@/lib/utils"

export interface UseAlertDialogProps extends Omit<CoreAlertDialogProps, 'id'> {
    id?: string
    defaultOpen?: boolean
}

export interface UseAlertDialogEmits {
    (e: 'update:open', value: boolean): void
    (e: 'openChange', value: boolean): void
}

let staticId = 0

export function useAlertDialog(props: UseAlertDialogProps, emit: UseAlertDialogEmits) {
    const localId = `alert-dialog-${++staticId}`

    const machineProps = computed(() => ({
        id: props.id ?? localId,
        open: props.open,
        defaultOpen: props.defaultOpen ?? false,
        role: 'alertdialog' as const, // Force alertdialog role
        modal: true, // Alerts are always modal
        onOpenChange(details: { open: boolean }) {
            emit('update:open', details.open)
            emit('openChange', details.open)
        },
    }))

    const service = useMachine(dialogMachine, machineProps)
    const api = computed(() => dialogConnect(service, normalizeProps))

    watch(
        () => props.open,
        (val?: boolean) => {
            if (val !== undefined && val !== api.value.open) {
                api.value.setOpen(val)
            }
        }
    )

    return api
}

.alert-dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 1000;
}

.alert-dialog-content {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 80%;
  max-width: 640rpx;
  background: #fff;
  border-radius: 16rpx;
  box-shadow: 0 16rpx 48rpx rgba(0, 0, 0, 0.18);
  z-index: 1001;
  overflow: hidden;
}

.alert-dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28rpx 28rpx 12rpx;
}

.alert-dialog-title {
  font-size: 32rpx;
  font-weight: 600;
  color: #111827;
}

.alert-dialog-close {
  font-size: 36rpx;
  line-height: 1;
  color: #6b7280;
}

.alert-dialog-body {
  padding: 0 28rpx 20rpx;
  font-size: 28rpx;
  line-height: 1.6;
  color: #374151;
}

.alert-dialog-footer {
  padding: 0 28rpx 28rpx;
}

.alert-dialog-actions {
  display: flex;
  gap: 16rpx;
}

.alert-dialog-cancel-btn,
.alert-dialog-confirm-btn {
  flex: 1;
  text-align: center;
  border-radius: 12rpx;
  padding: 18rpx 0;
  font-size: 28rpx;
}

.alert-dialog-cancel-btn {
  background: #f3f4f6;
  color: #374151;
}

.alert-dialog-confirm-btn {
  background: #111827;
  color: #ffffff;
}

import { resolveClasses } from '../utils'
import {
  dialogContentVariants,
  dialogOverlayVariants,
  dialogCloseVariants,
  dialogTitleVariants,
  dialogDescriptionVariants,
  dialogFooterVariants,
  dialogHeaderVariants,
  buttonVariants,
  alertDialogCancelVariants,
} from "@/lib/utils"
import { setupAlertDialogMachine } from './use-alert-dialog'

type AlertDialogApi = {
  open?: boolean
  backdropProps?: { onClick?: () => void }
  closeTriggerProps?: { onClick?: () => void }
  contentProps?: Record<string, string>
  titleProps?: Record<string, string>
  descriptionProps?: Record<string, string>
}

type MachineEvent = string | { type: string; [key: string]: object }
type MachineSend = (event: MachineEvent) => void

type AlertDialogInstance = WechatMiniprogram.Component.InstanceMethods<AlertDialogApi> & {
  _service?: object
  _cleanup?: () => void
  _send?: MachineSend
  _connect?: (state: object, send: MachineSend) => AlertDialogApi
  data: {
    api: AlertDialogApi
  }
  properties: {
    open: boolean
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    open: { type: Boolean, value: false },
    showTrigger: { type: Boolean, value: true },
    showClose: { type: Boolean, value: true },
    className: { type: String, value: '' },
    title: { type: String, value: '' },
    description: { type: String, value: '' },
    cancelText: { type: String, value: '' },
    confirmText: { type: String, value: '' },
  },

  data: {
    api: {} as AlertDialogApi,
    overlayClass: '',
    contentClass: '',
    titleClass: '',
    descriptionClass: '',
    footerClass: '',
    headerClass: '',
    cancelClass: '',
    confirmClass: '',
    closeClass: '',
  },

  lifetimes: {
    attached() {
      const self = this as AlertDialogInstance
      const { controller, connect } = setupAlertDialogMachine(this)

      self._service = controller.service
      self._cleanup = controller.start()
      self._send = controller.send as MachineSend
      self._connect = connect
    },
    detached() {
      const self = this as AlertDialogInstance
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as AlertDialogInstance
      if (!state || !self._send || !self._connect) return

      const api = self._connect(state, self._send) as AlertDialogApi

      const overlayClass = resolveClasses(dialogOverlayVariants())
      const contentClass = resolveClasses(dialogContentVariants(), this.properties.className)
      const titleClass = resolveClasses(dialogTitleVariants())
      const descriptionClass = resolveClasses(dialogDescriptionVariants())
      const footerClass = resolveClasses(dialogFooterVariants())
      const headerClass = resolveClasses(dialogHeaderVariants())
      const cancelClass = resolveClasses(alertDialogCancelVariants())
      const confirmClass = resolveClasses(buttonVariants())
      const closeClass = resolveClasses(dialogCloseVariants())

      this.setData({
        api,
        overlayClass,
        contentClass,
        titleClass,
        descriptionClass,
        footerClass,
        headerClass,
        cancelClass,
        confirmClass,
        closeClass
      })
    },

    'open': function (val) {
      const self = this as AlertDialogInstance
      if (self._service) {
        if (val !== self.data.api.open) {
          self._send?.(val ? 'OPEN' : 'CLOSE')
        }
      }
    },
  },

  methods: {
    onTriggerTap() {
      const self = this as AlertDialogInstance
      self._send?.('OPEN')
    },
    onBackdropTap() {
      const self = this as AlertDialogInstance
      self.data.api.backdropProps?.onClick?.()
    },
    onCloseTap() {
      const self = this as AlertDialogInstance
      self.data.api.closeTriggerProps?.onClick?.()
    },
    onCancelTap() {
      this.triggerEvent('cancel')
      const self = this as AlertDialogInstance
      self._send?.('CLOSE')
    },
    onConfirmTap() {
      this.triggerEvent('confirm')
      const self = this as AlertDialogInstance
      self._send?.('CLOSE')
    },
    noop() { }
  },
})
